+  private class FunctionDeclarationAlias extends AliasUsage {
+    private final String globalName;
+    private final AbstractCompiler compiler;
+
+    FunctionDeclarationAlias(Var aliasVar, Node aliasReference, String globalName,
+        AbstractCompiler compiler) {
+      super(aliasVar, aliasReference);
+      this.globalName = globalName;
+      this.compiler = compiler;
+    }
+
+    @Override
+    public boolean referencesOtherAlias() {
+      // Function declarations don't reference other aliases
+      return false;
+    }
+
+    @Override
+    public void applyAlias() {
+      // Replace the reference with the scoped name
+      aliasReference.getParent().replaceChild(
+          aliasReference,
+          NodeUtil.newQualifiedNameNode(
+              compiler.getCodingConvention(), globalName, aliasReference, null));
+    }
+  }
+

   private class Traversal implements NodeTraversal.ScopedCallback {
     // The job of this class is to collect these three data sets.
@@ -252,6 +279,9 @@ class ScopedAliases implements HotSwapCompilerPass {
     // This map is temporary and cleared for each scope.
     private final Map<String, Var> aliases = Maps.newHashMap();

+    // Map to track scoped names for function declarations
+    private final Map<String, String> functionDeclarationGlobalNames = Maps.newHashMap();
+
     // Suppose you create an alias.
     // var x = goog.x;
     // As a side-effect, this means you can shadow the namespace 'goog'
@@ -309,6 +339,7 @@ class ScopedAliases implements HotSwapCompilerPass {
       if (t.getScopeDepth() == 2) {
         renameNamespaceShadows(t);
         aliases.clear();
+        functionDeclarationGlobalNames.clear();
         forbiddenLocals.clear();
         transformation = null;
         hasNamespaceShadows = false;
@@ -414,6 +445,53 @@ class ScopedAliases implements HotSwapCompilerPass {
                   compiler.getCodingConvention(), globalName, n, name));

           recordAlias(v);
+        } else if (parent.isFunction()) {
+          // Handle function declarations by converting them to var declarations
+          Node functionNode = parent;
+          Node grandparent = functionNode.getParent();
+          Node scopeBlock = grandparent;
+
+          // Find the goog.scope block - traverse up to find the BLOCK node
+          while (scopeBlock != null && !scopeBlock.isBlock()) {
+            scopeBlock = scopeBlock.getParent();
+          }
+
+          String name = n.getString();
+          int nameCount = scopedAliasNames.count(name);
+          scopedAliasNames.add(name);
+          String globalName =
+              "$jscomp.scope." + name + (nameCount == 0 ? "" : ("$" + nameCount));
+
+          compiler.ensureLibraryInjected("base");
+
+          // Create an unnamed version of the function
+          Node value = functionNode.cloneTree();
+          value.getFirstChild().setString("");
+
+          // Add $jscomp.scope.name = function() {};
+          Node newDecl = NodeUtil.newQualifiedNameNodeDeclaration(
+              compiler.getCodingConvention(),
+              globalName,
+              value,
+              v.getJSDocInfo())
+              .useSourceInfoIfMissingFromForTree(n);
+          NodeUtil.setDebugInformation(
+              newDecl.getFirstChild().getFirstChild(), n, name);
+
+          // Add the assignment at the beginning of the scope block
+          if (scopeBlock != null && scopeBlock.hasChildren()) {
+            scopeBlock.addChildBefore(newDecl, scopeBlock.getFirstChild());
+          } else {
+            grandparent.addChildBefore(newDecl, functionNode);
+          }
+
+          // Remove the original function declaration
+          functionNode.detachFromParent();
+
+          // Add to aliases map and track the global name for later reference replacement
+          aliasDefinitionsInOrder.add(n);
+          aliases.put(name, v);
+          functionDeclarationGlobalNames.put(name, globalName);
         } else {
           // Do not other kinds of local symbols, like catch params.
           report(t, n, GOOG_SCOPE_NON_ALIAS_LOCAL, n.getString());
@@ -543,13 +621,20 @@ class ScopedAliases implements HotSwapCompilerPass {
       if (t.getScopeDepth() >= 2) {
         // Check if this name points to an alias.
         if (aliasVar != null) {
-          // Note, to support the transitive case, it's important we don't
-          // clone aliasedNode here.  For example,
-          // var g = goog; var d = g.dom; d.createElement('DIV');
-          // The node in aliasedNode (which is "g") will be replaced in the
-          // changes pass above with "goog".  If we cloned here, we'd end up
-          // with <code>g.dom.createElement('DIV')</code>.
-          aliasUsages.add(new AliasedNode(aliasVar, n));
+          String aliasName = aliasVar.getName();
+          // Check if this is a function declaration alias
+          if (functionDeclarationGlobalNames.containsKey(aliasName)) {
+            aliasUsages.add(new FunctionDeclarationAlias(
+                aliasVar, n, functionDeclarationGlobalNames.get(aliasName), compiler));
+          } else {
+            // Note, to support the transitive case, it's important we don't
+            // clone aliasedNode here.  For example,
+            // var g = goog; var d = g.dom; d.createElement('DIV');
+            // The node in aliasedNode (which is "g") will be replaced in the
+            // changes pass above with "goog".  If we cloned here, we'd end up
+            // with <code>g.dom.createElement('DIV')</code>.
+            aliasUsages.add(new AliasedNode(aliasVar, n));
+          }
         }

         JSDocInfo info = n.getJSDocInfo();
